                    "photo" -> e.getJSONObject("video").getJSONObject("input_photo")
                        .put("integrity_valid", false)

                    "id" -> e.getJSONObject("video").getJSONObject("input_photo")
                        .put("event_id", "other")

                    "hash" -> e.getJSONObject("video").getJSONObject("input_photo")
                        .put("sensor_sha256", "b".repeat(64))

                    "recipient" -> e.getJSONObject("assessment").put("recipient", "119-mock")
                    "mismatch" -> e.getJSONObject("data").getJSONObject("observations")
                        .put("plate", "DEMO-999")

                    "missing" -> e.getJSONObject("data").getJSONObject("observations")
                        .remove("plate")

                    "manual" -> e.getJSONObject("data").getJSONObject("context")
                        .remove("wanted_auto")

                    "pending" -> e.put("status", "pending_confirmation")
                    "receipt" -> e.getJSONArray("dispatches").getJSONObject(0)
                        .put("receipt", "MOCK-other")
                }
                if (change in listOf(
                        "photo",
                        "id",
                        "hash",
                        "missing_address",
                        "outside_latitude",
                        "blank_road"
                    )
                ) expect(
                    WantedAutoNotice.received(e) && !WantedAutoNotice.mediaValid(e) && DriverBriefPanel.verifiedBrief(
                        e
                    )?.second?.next == "현장 자료 확인 필요"
                )
                else expect(!WantedAutoNotice.received(e) && !DriverEventNoticeState.isEligible(e))
            }
            out.putString("result", "PASS $checks checks; predicates only")
            finish(Activity.RESULT_OK, out)
        } catch (t: Throwable) {
            out.putString("error", t.toString())
            finish(Activity.RESULT_CANCELED, out)
        }
    }
}
